    postionAsset(rootMesh, scaleNum) {
        let bb = rootMesh.getHierarchyBoundingVectors();
        let dist = 2;
        if (this.avManager.cc.getSettings().faceForward) {
            dist = -2;
        }
        let placementLocal = new babylonjs_1.Vector3(0, 0, -(scaleNum * dist));
        let placementGlobal = babylonjs_1.Vector3.TransformCoordinates(placementLocal, this.avatar.getWorldMatrix());
        let v = placementGlobal.subtract(this.avatar.position);
        let q = 0;
        if (v.x >= 0 && v.z >= 0) {
            q = 1;
        }
        else if (v.x <= 0 && v.z >= 0) {
            q = 2;
        }
        else if (v.x <= 0 && v.z <= 0) {
            q = 3;
        }
        else
            q = 4;
        let corner;
        if (q == 1) {
            corner = bb.min;
        }
        else if (q == 2) {
            corner = new babylonjs_1.Vector3(bb.max.x, bb.min.y, bb.min.z);
        }
        else if (q == 3) {
            corner = new babylonjs_1.Vector3(bb.max.x, bb.min.y, bb.max.z);
        }
        else
            corner = new babylonjs_1.Vector3(bb.min.x, bb.min.y, bb.max.z);
        if (rootMesh != null) {
            rootMesh.position.subtractInPlace(corner);
            rootMesh.position.addInPlace(placementGlobal);
            if (!this.isMeshSelected) {
                this.selectForEdit(rootMesh);
            }
            else {
                this.switchEditControl(rootMesh);
            }
            this.rootSelected = true;
            this.animateMesh(rootMesh);
        }
    }
