            x2 = positions[j + 3];
            y2 = positions[j + 4];
            z2 = positions[j + 5];
            positions[j + 3] = positions[j + 6];
            positions[j + 4] = positions[j + 7];
            positions[j + 5] = positions[j + 8];
            positions[j + 6] = x2;
            positions[j + 7] = y2;
